-- Initial service catalogue (from the Services Module specification): 9 categories, 82 subcategories, 284 services.
-- All start as "custom quote"; admin sets prices, descriptions and visibility in the app. Re-running adds nothing twice.
create temp table _svc_seed (j jsonb) on commit drop;
