Performance Management","KPI Development","Appraisal Systems"]],["Employee Engagement",["Engagement Programs","Culture Development","Retention Strategy"]],["HR Systems",["HR Process Digitalisation","HR Technology Advisory"]]]]]');
insert into public.service_categories (name, icon, sort_order)
select c.value->>0, c.value->>1, c.ordinality * 10 from _svc_seed d, jsonb_array_elements(d.j) with ordinality c
on conflict (name) do nothing;
insert into public.service_subcategories (category_id, name, sort_order)
select sc.id, s.value->>0, s.ordinality * 10
from _svc_seed d, jsonb_array_elements(d.j) c, jsonb_array_elements(c.value->2) with ordinality s, public.service_categories sc
where sc.name = c.value->>0
on conflict (category_id, name) do nothing;
insert into public.services (subcategory_id, name, sort_order)
select ss.id, i.value #>> '{}', i.ordinality * 10
from _svc_seed d, jsonb_array_elements(d.j) c, jsonb_array_elements(c.value->2) s, jsonb_array_elements(s.value->1) with ordinality i,
  public.service_categories sc, public.service_subcategories ss
where sc.name = c.value->>0 and ss.category_id = sc.id and ss.name = s.value->>0
on conflict (subcategory_id, name) do nothing;
